param([Parameter(Mandatory=$true)][string]$SourceProtocol,[Parameter(Mandatory=$true)][string]$OutputProtocol,[Parameter(Mandatory=$true)][string]$OldPrefix,[Parameter(Mandatory=$true)][string]$NewPrefix)
$ErrorActionPreference='Stop';$o=Get-Content -LiteralPath $SourceProtocol -Raw|ConvertFrom-Json
function Replace([object]$x){if($x -is [string]){return $x.Replace($OldPrefix,$NewPrefix)}if($x -is [System.Collections.IList]){$a=@();foreach($v in $x){$a+=,(Replace $v)};return $a}if($x -is [pscustomobject]){$h=[ordered]@{};foreach($p in $x.PSObject.Properties){$h[$p.Name]=Replace $p.Value};return [pscustomobject]$h}return $x}
$o=Replace $o;$b=[Text.UTF8Encoding]::new($false).GetBytes(($o|ConvertTo-Json -Depth 40)+"`n");$s=[IO.File]::Open($OutputProtocol,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$s.Write($b,0,$b.Length);$s.Flush($true)}finally{$s.Dispose()};Get-FileHash -LiteralPath $OutputProtocol -Algorithm SHA256|Select-Object -ExpandProperty Hash
